/// Searches for the first index `k` in `a[lo..hi)` such that:
///   - for all r in [lo, k): a[r] < x
///   - for all r in [k, hi): a[r] >= x
/// Equivalently, the lower-bound of `x` in the half-open range [lo, hi).
pub fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut lo = lo;
    let mut hi = hi;
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] < x {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo
}

/// Restricts the above search to the first 1000 elements of `a`.
/// Assumes `a.len() >= 1000` and that `a[0..1000]` is sorted in non‐decreasing order.
pub fn search_1000(a: &[i32], x: i32) -> usize {
    // we only look in the range [0, 1000)
    search_range_helper(a, x, 0, 1000)
}

